using System;using System.Linq;using System.Collections.Generic;using System.Globalization;using System.Text;
namespace BeamScheduleFormatter {
class PurlinProperties {
 public double Area,Ix,Iy,Ixy,Sx,Sy,Xbar,Ybar;public bool Verified;public readonly List<double[]> Points=new List<double[]>();
 public static PurlinProperties Calculate(SteelProfile p){if(p==null||p.Kind!="Purlin")throw new Exception("Choose a purlin profile.");double h=p.H,b=p.B,c=p.Lip,t=p.T;SteelWeight.Positive(h,b,c,t);if(h<=2*c||b<=2*t||c<=t)throw new Exception("Section dimensions do not fit.");bool z=p.Name.StartsWith("Z",StringComparison.OrdinalIgnoreCase);var rectangles=new List<double[]>();if(!z){rectangles.Add(new[]{0.0,0.0,t,h});rectangles.Add(new[]{t,0.0,b-t,t});rectangles.Add(new[]{t,h-t,b-t,t});rectangles.Add(new[]{b-t,t,t,c-t});rectangles.Add(new[]{b-t,h-c,t,c-t});}else{rectangles.Add(new[]{-t/2,0.0,t,h});rectangles.Add(new[]{t/2,h-t,b-t,t});rectangles.Add(new[]{-b+t/2,0.0,b-t,t});rectangles.Add(new[]{b-1.5*t,h-c,t,c-t});rectangles.Add(new[]{-b+t/2,t,t,c-t});}
  var result=new PurlinProperties();result.Area=rectangles.Sum(r=>r[2]*r[3]);result.Xbar=rectangles.Sum(r=>r[2]*r[3]*(r[0]+r[2]/2))/result.Area;result.Ybar=rectangles.Sum(r=>r[2]*r[3]*(r[1]+r[3]/2))/result.Area;
  foreach(var r in rectangles){double a=r[2]*r[3],x=r[0]+r[2]/2-result.Xbar,y=r[1]+r[3]/2-result.Ybar;result.Ix+=r[2]*Math.Pow(r[3],3)/12+a*y*y;result.Iy+=r[3]*Math.Pow(r[2],3)/12+a*x*x;result.Ixy+=a*x*y;foreach(double px in new[]{r[0],r[0]+r[2]})foreach(double py in new[]{r[1],r[1]+r[3]})result.Points.Add(new[]{px-result.Xbar,py-result.Ybar});}
  result.Sx=result.Ix/result.Points.Max(a=>Math.Abs(a[1]));result.Sy=result.Iy/result.Points.Max(a=>Math.Abs(a[0]));return result;
 }
 public void Validate(){SteelWeight.Positive(Area,Ix,Iy,Sx,Sy);if(double.IsNaN(Ixy)||double.IsInfinity(Ixy)||Ix*Iy-Ixy*Ixy<=0)throw new Exception("Section inertia matrix must be positive definite.");}
}
class PurlinDesignInput {
 public SteelProfile Profile;public PurlinProperties Properties;public string Name="Purlin",Support="Simply supported",Ceiling="Not supporting ceiling";public int SagRods;public double Span=5,Spacing=.4,Angle=13,Fy=248,E=200000,Dead=.35,Live=1,WindPressure=0,WindSuction=0;public bool AlternateIncrease=true;
 public void Validate(){if(Profile==null||Profile.Kind!="Purlin"||Properties==null)throw new Exception("Choose a profile and section properties.");Properties.Validate();SteelWeight.Positive(Span,Spacing,Fy,E);if(Span>100||Spacing>20||Fy>1000||E<10000||E>500000||double.IsNaN(Angle)||double.IsInfinity(Angle)||Angle<0||Angle>=90||SagRods<0||SagRods>2)throw new Exception("Check span, spacing, material, roof angle and sag rods (0-2).");foreach(double v in new[]{Dead,Live,WindPressure,WindSuction})if(double.IsNaN(v)||double.IsInfinity(v)||Math.Abs(v)>1000)throw new Exception("Check finite loads in kPa.");if(Dead<0||Live<0)throw new Exception("Dead and live area loads must be nonnegative.");if(!new[]{"Simply supported","Cantilever"}.Contains(Support)||!new[]{"Not supporting ceiling","Supporting nonplaster ceiling","Supporting plaster ceiling"}.Contains(Ceiling))throw new Exception("Choose support and ceiling type.");}
}
class PurlinLoadCase {public string Name;public bool Alternate;public double Normal,Tangential,Mx,My,Ratio;}
class PurlinDesignResult {
 public readonly List<PurlinLoadCase> Cases=new List<PurlinLoadCase>();public double Dx,Dy,Lx,Ly,Fbx,Fby,Cx,Cy,Basic,Alternate,LiveDeflection,TotalDeflection,LiveLimit,TotalLimit;public bool WithinWorkbookChecks{get{return Basic<=1&&Alternate<=1&&LiveDeflection<=LiveLimit&&TotalDeflection<=TotalLimit;}}
}
static class PurlinDesigner {
 public static PurlinDesignResult Calculate(PurlinDesignInput input){input.Validate();var p=input.Properties;double angle=input.Angle*Math.PI/180;var r=new PurlinDesignResult();double dead=input.Dead*input.Spacing+input.Profile.KgM*9.81/1000;r.Dx=dead*Math.Cos(angle);r.Dy=dead*Math.Sin(angle);r.Lx=input.Live*input.Spacing*Math.Cos(angle);r.Ly=input.Live*input.Spacing*Math.Sin(angle);double wp=input.WindPressure*input.Spacing,ws=input.WindSuction*input.Spacing;bool cant=input.Support=="Cantilever";r.Cx=cant?.5:.125;r.Cy=(cant?new[]{.5,.028544,.014288}:new[]{.125,.03125,1.0/90})[input.SagRods];r.Fbx=(input.Profile.B/input.Profile.T<.38*Math.Sqrt(input.E/input.Fy)?.66:.60)*input.Fy;r.Fby=((input.Profile.H-2*input.Profile.T)/input.Profile.T<3.76*Math.Sqrt(input.E/input.Fy)?.66:.60)*input.Fy;
  Action<string,double,double,bool> add=(name,x,y,alternate)=>{double mx=r.Cx*x*input.Span*input.Span,my=r.Cy*y*input.Span*input.Span;double factor=alternate&&input.AlternateIncrease?4.0/3:1;r.Cases.Add(new PurlinLoadCase{Name=name,Normal=x,Tangential=y,Mx=mx,My=my,Alternate=alternate,Ratio=Interaction(p,mx,my,r.Fbx*factor,r.Fby*factor)});};
  add("D + L",r.Dx+r.Lx,r.Dy+r.Ly,false);add("D + 0.6Wp",r.Dx+.6*wp,r.Dy,false);add("D + 0.6Ws",r.Dx+.6*ws,r.Dy,false);add("D + 0.75(L + 0.6Wp)",r.Dx+.75*(r.Lx+.6*wp),r.Dy+.75*r.Ly,true);add("D + 0.75(L + 0.6Ws)",r.Dx+.75*(r.Lx+.6*ws),r.Dy+.75*r.Ly,true);add("0.6D + 0.6Wp",.6*r.Dx+.6*wp,.6*r.Dy,true);add("0.6D + 0.6Ws",.6*r.Dx+.6*ws,.6*r.Dy,true);
  foreach(bool alternate in new[]{false,true}){var cases=r.Cases.Where(c=>c.Alternate==alternate).ToList();double mx=cases.Max(c=>Math.Abs(c.Mx)),my=cases.Max(c=>Math.Abs(c.My)),factor=alternate&&input.AlternateIncrease?4.0/3:1;double envelope=Interaction(p,mx,my,r.Fbx*factor,r.Fby*factor);if(alternate)r.Alternate=envelope;else r.Basic=envelope;}
  double coefficient=cant?1.0/8:5.0/384;r.LiveDeflection=Deflection(p,r.Lx,r.Ly,input.Span,input.E,coefficient);r.TotalDeflection=Deflection(p,r.Dx+r.Lx,r.Dy+r.Ly,input.Span,input.E,coefficient);int ceiling=input.Ceiling=="Supporting plaster ceiling"?0:input.Ceiling=="Supporting nonplaster ceiling"?1:2;int[] liveLimits={360,240,180},totalLimits={240,180,120};r.LiveLimit=input.Span*1000/liveLimits[ceiling];r.TotalLimit=input.Span*1000/totalLimits[ceiling];return r;
 }
 internal static double Interaction(PurlinProperties p,double mx,double my,double fbx,double fby){if(Math.Abs(p.Ixy)<1e-8)return Math.Abs(mx)*1e6/p.Sx/fbx+Math.Abs(my)*1e6/p.Sy/fby;double determinant=p.Ix*p.Iy-p.Ixy*p.Ixy;return p.Points.Max(point=>Math.Abs(mx*1e6*(-p.Ixy*point[0]+p.Iy*point[1])/determinant)/fbx+Math.Abs(my*1e6*(p.Ix*point[0]-p.Ixy*point[1])/determinant)/fby);}
 internal static double Deflection(PurlinProperties p,double normal,double tangential,double span,double e,double coefficient){double determinant=p.Ix*p.Iy-p.Ixy*p.Ixy,factor=coefficient*Math.Pow(span*1000,4)/e;double x=factor*(p.Ix*tangential-p.Ixy*normal)/determinant,y=factor*(p.Iy*normal-p.Ixy*tangential)/determinant;return Math.Sqrt(x*x+y*y);}
 public static string Report(PurlinDesignInput input,PurlinDesignResult r){return DetailedDesignReports.Purlin(input,r);}
 internal static string ReferenceSummary(PurlinDesignInput input,PurlinDesignResult r){var b=new StringBuilder();b.AppendLine("PURLIN DESIGN | WORKBOOK ASD FLEXURE & DEFLECTION");b.AppendLine(input.Name+" | "+input.Profile.Name+" | "+input.Support);b.AppendLine(input.Profile.Source);b.AppendLine("METHOD SCOPE: workbook gross-section checks. Effective-width, local/distortional/lateral buckling, shear, web crippling, connections and restraint capacity are not checked here.");b.AppendLine("Section properties: "+(input.Properties.Verified?"user-supplied verified inputs":"calculated nonoverlapping rectangular plates; bends/radii neglected, NOT manufacturer-certified"));b.AppendLine("Overall member adequacy requires the remaining cold-formed steel checks.");b.AppendLine(string.Format(CultureInfo.InvariantCulture,"L={0:0.###}m; spacing={1:0.###}m; angle={2:0.###}deg; sag rods={3}; Fy={4:0.###}MPa; E={5:0.###}MPa",input.Span,input.Spacing,input.Angle,input.SagRods,input.Fy,input.E));b.AppendLine(string.Format(CultureInfo.InvariantCulture,"Area={0:0.###}mm2; Ix={1:0.###}mm4; Iy={2:0.###}mm4; Ixy={3:0.###}mm4; Sx={4:0.###}mm3; Sy={5:0.###}mm3",input.Properties.Area,input.Properties.Ix,input.Properties.Iy,input.Properties.Ixy,input.Properties.Sx,input.Properties.Sy));b.AppendLine("Mass from handbook: "+input.Profile.KgM.ToString("0.###",CultureInfo.InvariantCulture)+"kg/m; self-weight=mass x 9.81 / 1000 kN/m.");b.AppendLine(string.Format(CultureInfo.InvariantCulture,"Loads kPa: superimposed D={0:0.###}, L={1:0.###}, Wp={2:0.###}, Ws={3:0.###}. Wind is signed normal pressure; suction normally negative.",input.Dead,input.Live,input.WindPressure,input.WindSuction));b.AppendLine(string.Format(CultureInfo.InvariantCulture,"D normal/tangential={0:0.######}/{1:0.######} kN/m; L={2:0.######}/{3:0.######} kN/m",r.Dx,r.Dy,r.Lx,r.Ly));b.AppendLine(string.Format(CultureInfo.InvariantCulture,"Workbook Fbx={0:0.###}MPa; Fby={1:0.###}MPa; Cx={2:0.######}; Cy={3:0.######}",r.Fbx,r.Fby,r.Cx,r.Cy));b.AppendLine("LOAD COMBINATIONS | kN/m, kN.m, ratio");foreach(var c in r.Cases)b.AppendLine(string.Format(CultureInfo.InvariantCulture,"{0,-26} Wx={1,10:0.######} Wy={2,10:0.######} Mx={3,10:0.######} My={4,10:0.######} interaction={5:0.######}",c.Name,c.Normal,c.Tangential,c.Mx,c.My,c.Ratio));b.AppendLine(string.Format(CultureInfo.InvariantCulture,"Independent component envelopes (conservative): basic={0:0.######}; alternate={1:0.######}; limit <=1",r.Basic,r.Alternate));b.AppendLine("Alternate allowable stress increase: "+(input.AlternateIncrease?"4/3, as in supplied workbook":"disabled"));b.AppendLine(string.Format(CultureInfo.InvariantCulture,"Live deflection={0:0.###}mm / limit {1:0.###}mm; D+L deflection={2:0.###}mm / limit {3:0.###}mm",r.LiveDeflection,r.LiveLimit,r.TotalDeflection,r.TotalLimit));b.AppendLine(r.WithinWorkbookChecks?"LISTED WORKBOOK CHECKS SATISFIED; additional member checks remain.":"LISTED WORKBOOK CHECKS EXCEEDED.");b.AppendLine("SOURCE / ADJUSTMENTS");b.AppendLine("PS Design of Purlin.xlsm: Y101:Y155 (ASD combinations, allowable stresses, interaction and ceiling limits). No macros or license/project metadata are included.");b.AppendLine("Normal-axis Cx uses 1/8 for simply supported and 1/2 for cantilever. Sag rods do not reduce the normal-axis span (workbook 2-rod 1/9 is not used). Tangential coefficients follow the supplied workbook and assume effective sag-rod restraint.");b.AppendLine("Deflection uses full-span 5wL^4/(384EI) for simply supported or wL^4/(8EI) for cantilever; workbook cantilever 5/384 is corrected. No sag-rod deflection reduction. Nonzero Ixy uses coupled unsymmetric bending for Z sections.");b.AppendLine("Regan 2026 handbook lists dimensions/mass only. Calculated properties do not reproduce the workbook's inconsistent centroid denominator; verified properties may be entered separately.");b.AppendLine("Cantilever reference: NASA Mechanical Design Reliability Monograph, Eq.1.19, https://extapps.ksc.nasa.gov/Reliability/Documents/Mechanical-Design-Reliability-Monograph.pdf");return b.ToString();}
}
}
